head.script:
// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
//
// ********************************************************************

scwin.gIsurCd;
scwin.gSeq;
scwin.gDepCd;
scwin.gEmpNo;
X < !정보--;
셋팅-- > function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    scwin.gSeq = $c.frame.path("../").scwin.gSeq;
} < !정보--;
데이타;
읽어오기-- > async function() {
    const sbmOptions = {
        id : "sbm_dts_outdir_info",
        action : "/OutDir.do",
        ref : "",
        target : "dts_outdir_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        fn_GetParentValue();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_outdir_info",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_outdir_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 가우스헤더 셋팅
        const sbmOptions2 = {
            id : "sbm_dts_outdir",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_outdir=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        //  정보 읽어오기
        fn_ReadInfo();
        txb_ld_mkt_tp_cd.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39001.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39001.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39001.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name dts_outdir_info_OnLoadError
 * @description dts_outdir_info 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_outdir_info_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_outdir_info);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39001.dts_outdir_info_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_outdir_info_OnLoadCompleted
 * @description dts_outdir_info 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_outdir_info_OnLoadCompleted = function(rowcount) {
    try {
        scwin.chkBtn();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39001.dts_outdir_info_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_outdir_info_OnSuccess
 * @description outdir info On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_outdir_info_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        // self.close();
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39001.trs_outdir_info_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_outdir_info_OnFail
 * @description outdir info On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_outdir_info_OnFail = async function() {
    try {
        await $c.win.alert('trs_outdir_info.OnFail() :' + trs_outdir_info.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39001.trs_outdir_info_OnFail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name update
 * @description 사외이사 정보 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    // if(getObjectValue(edt_encryp_birthdd) != "" || getObjectValue(edt_encryp_birthdd).indexOf(" ") != "" ) {
    if (edt_encryp_birthdd.getValue() !== "") {
        if (Number(edt_encryp_birthdd.getValue()) > $c.ut.cGetToday("yyyymmdd").substring(0, 4)) {
            await $c.win.alert("현재 연도보다 출생 연도가 큽니다.");
            edt_encryp_birthdd.focus();
            return;
        }
        if (edt_encryp_birthdd.getValue().length < 4) {
            await $c.win.alert("출생연도는 4자리 입니다.");
            edt_encryp_birthdd.focus();
            return;
        }
    }
    dts_outdir.insertRow();
    dts_outdir.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_outdir.setCellData(1, "SEQ", scwin.gSeq);
    dts_outdir.setCellData(1, "OUTDIR_NM", txb_outdir_nm.getValue());
    dts_outdir.setCellData(1, "ENCRYP_BIRTHDD", edt_encryp_birthdd.getValue());
    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        trs_outdir_info.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_outdir_info",
            action : "/OutDir.do",
            ref : "dts_outdir",
            target : "trs_outdir_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description 사외이사 정보 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    const rtn = confirm('삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_outdir.insertRow();
        dts_outdir.setCellData(1, "ISUR_CD", scwin.gIsurCd);
        dts_outdir.setCellData(1, "SEQ", scwin.gSeq);
        trs_outdir_info.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_outdir_info",
            action : "/OutDir.do",
            ref : "dts_outdir",
            target : "trs_outdir_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name chkBtn
 * @description chk Btn 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkBtn = function() {
    const mktId = js_market;
    // 다른 시장의 데이터는 삭제, 수정 불가
    if (js_market !== '9') {
        if (txb_ld_mkt_tp_cd.getValue() !== mktId) {
            btn_Delete.hide();
            btn_Save.hide();
        }
    }
};
